insert into public.scenarios (id,category,title,description,sender,message,fake_link,difficulty_level,minutes,icon) values
(1,'{"bg":"ФИШИНГ","en":"PHISHING"}','{"bg":"Награда с уловка","en":"A prize with a catch"}','{"bg":"Съобщение обещава безплатни предмети за любимата ти игра. Ще разпознаеш ли измамата?","en":"A message promises free items for your favourite game. Can you spot the scam?"}','Game Rewards','{"bg":"Поздравления! 🎁 Спечели 5000 безплатни монети!\n\nСамо за следващите 10 минути: влез с игровия си акаунт през линка и потвърди паролата си, за да вземеш наградата.","en":"Congratulations! 🎁 You won 5,000 free coins!\n\nFor the next 10 minutes only: sign in with your gaming account using the link and confirm your password to claim your prize."}','https://game-rewards.invalid/claim',1,2,'◇'),
(2,'{"bg":"ЗАЩИТА НА АКАУНТА","en":"ACCOUNT SECURITY"}','{"bg":"Кодът е само за теб","en":"That code is yours"}','{"bg":"Някой се представя за поддръжка и иска твоя код за вход. Как ще защитиш акаунта си?","en":"Someone claims to be support and asks for your login code. How will you protect your account?"}','Support Helper','{"bg":"Здравей! Забелязахме проблем с твоя профил. Аз съм от поддръжката.\n\nИзпрати ми шестцифрения код, който току-що получи, за да не бъде блокиран акаунтът ти.","en":"Hi! We noticed a problem with your profile. I work for support.\n\nSend me the six-digit code you just received so your account does not get blocked."}','Support chat · #4821',1,2,'⌘'),
(3,'{"bg":"ОБЩУВАНЕ ОНЛАЙН","en":"ONLINE COMMUNICATION"}','{"bg":"Не си сам в чата","en":"You are not alone"}','{"bg":"В групов чат се появяват обиди към твой съученик. Избери действие, което наистина помага.","en":"A classmate is being insulted in a group chat. Choose an action that actually helps."}','Class group','{"bg":"В групата няколко души споделят унизителна снимка на твой съученик и го обиждат.\n\n„Прати я на всички! Нека целият клас я види!“","en":"Several people in the group share an embarrassing photo of your classmate and insult them.\n\n“Send it to everyone! Let the whole class see it!”"}','',1,3,'☏'),
(4,'{"bg":"ПРОБИВ В КЛУБА","en":"CLUB BREACH"}','{"bg":"Приятел или измамник?","en":"Friend or impostor?"}','{"bg":"Разследвай следващата следа и защити училищния клуб.","en":"Investigate the next clue and protect the school club."}','SafeNet Club','{"bg":"Профилът на приятел ти пише: „Спешно ми купи ваучер и прати кода! Не мога да говоря.“ Как проверяваш самоличността?","en":"A friend messages: “Buy a voucher urgently and send me the code! I cannot talk.” How do you check their identity?"}','',2,3,'◇'),
(5,'{"bg":"ПРОБИВ В КЛУБА","en":"CLUB BREACH"}','{"bg":"Тайният турнир","en":"The secret tournament"}','{"bg":"Разследвай следващата следа и защити училищния клуб.","en":"Investigate the next clue and protect the school club."}','SafeNet Club','{"bg":"Получаваш файл tournament-cheat.exe, уж нужен за училищния турнир. Изпращачът иска да изключиш антивирусната защита.","en":"You receive tournament-cheat.exe, supposedly needed for the school tournament. The sender asks you to disable antivirus."}','',2,3,'◇'),
(6,'{"bg":"ПРОБИВ В КЛУБА","en":"CLUB BREACH"}','{"bg":"Ключът към клуба","en":"The club password"}','{"bg":"Разследвай следващата следа и защити училищния клуб.","en":"Investigate the next clue and protect the school club."}','SafeNet Club','{"bg":"Клубът създава нов акаунт. Кой подход ще намали риска след съмнителните съобщения?","en":"The club is creating a new account. Which approach reduces risk after the suspicious messages?"}','',2,3,'◇'),
(7,'{"bg":"ОПЕРАЦИЯ ВЪЗСТАНОВЯВАНЕ","en":"RECOVERY OPERATION"}','{"bg":"QR капан","en":"The QR trap"}','{"bg":"Разследвай следващата следа и защити училищния клуб.","en":"Investigate the next clue and protect the school club."}','SafeNet Club','{"bg":"Плакат за турнира има нов QR стикер върху стария. Отворената страница иска вход в училищния акаунт.","en":"The tournament poster has a new QR sticker over the old one. The page asks you to sign in to your school account."}','',3,3,'◇'),
(8,'{"bg":"ОПЕРАЦИЯ ВЪЗСТАНОВЯВАНЕ","en":"RECOVERY OPERATION"}','{"bg":"Непознато влизане","en":"Unknown login"}','{"bg":"Разследвай следващата следа и защити училищния клуб.","en":"Investigate the next clue and protect the school club."}','SafeNet Club','{"bg":"Официалното приложение показва непозната активна сесия. Вече си въвел паролата си в съмнителна страница. Как реагираш?","en":"The official app shows an unknown active session. You already entered your password on a suspicious page. What do you do?"}','',3,3,'◇'),
(9,'{"bg":"ФИНАЛНА МИСИЯ","en":"FINAL MISSION"}','{"bg":"Спаси училищния турнир","en":"Save the school tournament"}','{"bg":"Разследвай следващата следа и защити училищния клуб.","en":"Investigate the next clue and protect the school club."}','SafeNet Club','{"bg":"Разкри измамата. Фалшивият профил още изпраща линкове към клуба. Как защитаваш останалите, без да разпространяваш опасността?","en":"You uncovered the scam. The fake account is still sending links to the club. How do you protect others without spreading the threat?"}','',3,3,'★')
insert into public.choices (id,scenario_id,position,text,is_correct,feedback) values
(11,1,1,'{"bg":"Отварям линка и въвеждам паролата си.","en":"Open the link and enter my password."}',false,'{"bg":"Фалшивите награди могат да откраднат паролата ти. Спешният срок и непознатият адрес са предупредителни сигнали. Провери офертата през официалното приложение.","en":"Fake prizes can steal your password. Urgency and an unfamiliar address are warning signs. Check the offer in the official app."}'),
(12,1,2,'{"bg":"Проверявам през официалното приложение и докладвам съобщението.","en":"Check the official app and report the message."}',true,'{"bg":"Точно така! Отвори официалното приложение самостоятелно, без подозрителния линк. Не споделяй парола и докладвай измамата.","en":"Exactly! Open the official app yourself without using the suspicious link. Do not share your password and report the scam."}'),
(13,1,3,'{"bg":"Препращам линка на приятел да го изпробва.","en":"Forward the link to a friend to try it."}',false,'{"bg":"Така излагаш и приятеля си на риск. Не разпространявай подозрителни линкове. Провери източника и предупреди приятелите си.","en":"This puts your friend at risk too. Do not spread suspicious links. Check the source and warn your friends."}'),
(21,2,1,'{"bg":"Изпращам кода, защото е от поддръжката.","en":"Send the code because they work for support."}',false,'{"bg":"Всеки може да се представи за поддръжка. Кодът може да позволи на измамника да влезе в акаунта ти. Не го споделяй.","en":"Anyone can pretend to be support. The code may let the scammer access your account. Never share it."}'),
(22,2,2,'{"bg":"Питам дали ще ми даде награда срещу кода.","en":"Ask for a reward in exchange for the code."}',false,'{"bg":"Кодовете за вход не се разменят за награди. Прекрати разговора и потърси официалната поддръжка през приложението.","en":"Login codes should never be traded for rewards. End the conversation and contact official support through the app."}'),
(23,2,3,'{"bg":"Не споделям кода и проверявам през официалната поддръжка.","en":"Keep the code private and check with official support."}',true,'{"bg":"Правилно! Кодът за вход е личен. Отвори настройките за сигурност и провери активните сесии, ако не си поискал този код.","en":"Correct! Your login code is private. Open your security settings and check active sessions if you did not request the code."}'),
(31,3,1,'{"bg":"Не препращам снимката, подкрепям съученика и търся доверен възрастен.","en":"Do not forward the photo, support my classmate and tell a trusted adult."}',true,'{"bg":"Добър избор. Не разпространявай обидното съдържание. Запази доказателство, ако е безопасно, докладвай и потърси помощ от учител или родител.","en":"Good choice. Do not spread hurtful content. Keep evidence if it is safe, report it and ask a teacher or parent for help."}'),
(32,3,2,'{"bg":"Препращам снимката, защото всички го правят.","en":"Forward the photo because everyone else does."}',false,'{"bg":"Препращането увеличава вредата. Подкрепи съученика, докладвай съдържанието и потърси доверен възрастен.","en":"Forwarding increases the harm. Support your classmate, report the content and tell a trusted adult."}'),
(33,3,3,'{"bg":"Започвам да обиждам нападателите.","en":"Start insulting the attackers."}',false,'{"bg":"Отговорът с обиди може да задълбочи конфликта. Подкрепи пострадалия спокойно и потърси помощ, вместо да ескалираш.","en":"Insults can make the conflict worse. Calmly support the person being targeted and ask for help instead of escalating."}'),
(41,4,1,'{"bg":"Пращам кода веднага.","en":"Send the code immediately."}',false,'{"bg":"Провери по независим канал. Профилната снимка и познатото име не доказват кой пише.","en":"Verify through a separate channel. A familiar name and photo do not prove who is typing."}'),
(42,4,2,'{"bg":"Обаждам се на познатия му номер.","en":"Call their known phone number."}',true,'{"bg":"Провери по независим канал. Профилната снимка и познатото име не доказват кой пише.","en":"Verify through a separate channel. A familiar name and photo do not prove who is typing."}'),
(43,4,3,'{"bg":"Искам снимка на профила му.","en":"Ask for their profile picture."}',false,'{"bg":"Провери по независим канал. Профилната снимка и познатото име не доказват кой пише.","en":"Verify through a separate channel. A familiar name and photo do not prove who is typing."}'),
(51,5,1,'{"bg":"Изключвам защитата временно.","en":"Disable protection temporarily."}',false,'{"bg":"Искането да изключиш защитата е сигнал за риск. Използвай само потвърдени източници и не разпространявай файла.","en":"Being asked to disable protection is a warning sign. Use verified sources and do not spread the file."}'),
(52,5,2,'{"bg":"Пращам файла на съучениците.","en":"Forward the file to classmates."}',false,'{"bg":"Искането да изключиш защитата е сигнал за риск. Използвай само потвърдени източници и не разпространявай файла.","en":"Being asked to disable protection is a warning sign. Use verified sources and do not spread the file."}'),
(53,5,3,'{"bg":"Не стартирам файла и проверявам при организатора.","en":"Do not run it; check with the organiser."}',true,'{"bg":"Искането да изключиш защитата е сигнал за риск. Използвай само потвърдени източници и не разпространявай файла.","en":"Being asked to disable protection is a warning sign. Use verified sources and do not spread the file."}'),
(61,6,1,'{"bg":"Уникална дълга парола и двуфакторна защита.","en":"A unique long password and two-factor authentication."}',true,'{"bg":"Уникалната парола ограничава щетите при пробив в друг сайт. Вторият фактор добавя допълнителна проверка.","en":"A unique password limits damage from another website’s breach. A second factor adds another check."}'),
(62,6,2,'{"bg":"Една парола за всички сайтове.","en":"One password for every site."}',false,'{"bg":"Уникалната парола ограничава щетите при пробив в друг сайт. Вторият фактор добавя допълнителна проверка.","en":"A unique password limits damage from another website’s breach. A second factor adds another check."}'),
(63,6,3,'{"bg":"Името на училището и годината.","en":"The school name and current year."}',false,'{"bg":"Уникалната парола ограничава щетите при пробив в друг сайт. Вторият фактор добавя допълнителна проверка.","en":"A unique password limits damage from another website’s breach. A second factor adds another check."}'),
(71,7,1,'{"bg":"Влизам, щом плакатът е в училище.","en":"Sign in because the poster is at school."}',false,'{"bg":"QR кодът е просто начин да отвориш адрес. Стикерите могат да се подменят; мястото на плаката не гарантира безопасност.","en":"A QR code simply opens an address. Stickers can be replaced; the poster’s location does not guarantee safety."}'),
(72,7,2,'{"bg":"Проверявам адреса с организатора, без да въвеждам данни.","en":"Check the address with the organiser without entering data."}',true,'{"bg":"QR кодът е просто начин да отвориш адрес. Стикерите могат да се подменят; мястото на плаката не гарантира безопасност.","en":"A QR code simply opens an address. Stickers can be replaced; the poster’s location does not guarantee safety."}'),
(73,7,3,'{"bg":"Пробвам с паролата на приятел.","en":"Try a friend’s password."}',false,'{"bg":"QR кодът е просто начин да отвориш адрес. Стикерите могат да се подменят; мястото на плаката не гарантира безопасност.","en":"A QR code simply opens an address. Stickers can be replaced; the poster’s location does not guarantee safety."}'),
(81,8,1,'{"bg":"Изчаквам да изчезне.","en":"Wait for it to disappear."}',false,'{"bg":"Действай през официалното приложение. Прекрати чуждите сесии, смени компрометираните пароли и потърси доверен възрастен.","en":"Use the official app. End unknown sessions, change compromised passwords and ask a trusted adult for help."}'),
(82,8,2,'{"bg":"Изтривам само съобщението.","en":"Only delete the message."}',false,'{"bg":"Действай през официалното приложение. Прекрати чуждите сесии, смени компрометираните пароли и потърси доверен възрастен.","en":"Use the official app. End unknown sessions, change compromised passwords and ask a trusted adult for help."}'),
(83,8,3,'{"bg":"Сменям паролата през официалния сайт, прекратявам чуждите сесии и търся помощ.","en":"Change the password on the official site, end unknown sessions and ask for help."}',true,'{"bg":"Действай през официалното приложение. Прекрати чуждите сесии, смени компрометираните пароли и потърси доверен възрастен.","en":"Use the official app. End unknown sessions, change compromised passwords and ask a trusted adult for help."}'),
(91,9,1,'{"bg":"Предупреждавам без активния линк, докладвам профила и уведомявам организатора.","en":"Warn others without the active link, report the account and tell the organiser."}',true,'{"bg":"Защитата е екипна работа. Предупреди ясно, без да споделяш пароли или опасни връзки. Организаторът може да потвърди официалните канали.","en":"Safety is teamwork. Warn clearly without sharing passwords or dangerous links. The organiser can confirm official channels."}'),
(92,9,2,'{"bg":"Публикувам паролата на пострадалия като доказателство.","en":"Publish the victim’s password as evidence."}',false,'{"bg":"Защитата е екипна работа. Предупреди ясно, без да споделяш пароли или опасни връзки. Организаторът може да потвърди официалните канали.","en":"Safety is teamwork. Warn clearly without sharing passwords or dangerous links. The organiser can confirm official channels."}'),
(93,9,3,'{"bg":"Препращам опасния линк на всички за проверка.","en":"Forward the dangerous link for everyone to test."}',false,'{"bg":"Защитата е екипна работа. Предупреди ясно, без да споделяш пароли или опасни връзки. Организаторът може да потвърди официалните канали.","en":"Safety is teamwork. Warn clearly without sharing passwords or dangerous links. The organiser can confirm official channels."}')
